// Reading tests 027 → 095.
import type { ReadingTest } from '../reading-tests';

export const DATA_22: ReadingTest[] = [
  { id: "rd-027", num: 27, title: "Đề 027", timeMin: 60, parts: [
    { title: "Reading Habits Among Today's Youth", paragraphs: ["Across many countries, surveys carried out over the last ten years suggest that fewer teenagers now open a printed book purely for pleasure than their parents did at the same age. Some researchers link this change to busier daily schedules. Others point instead to the sheer number of entertainment options competing for a teenager's attention each evening, from video platforms to messaging apps. The picture, however, is not simply one of decline, because the very meaning of \"reading\" has broadened well beyond ink on paper, now including text on screens, in apps, and inside games.", "One clear factor behind the shift is competition for time. Teenagers today juggle schoolwork, part-time jobs, and social commitments that previous generations managed with fewer digital distractions pulling at every free minute. A short video or a group chat notification delivers entertainment in seconds, while a novel demands sustained attention across many pages. Even so, digital habits have not erased reading altogether; they have simply changed its shape, moving much of it onto phones, tablets, and laptop screens where a young person might scroll through news, fan fiction, or serialized stories between other tasks.", "Despite these pressures, a meaningful share of young readers still finish books for enjoyment rather than for school assignments. Public libraries in several cities report steady demand among teenagers for graphic novels, fantasy series, and audiobooks that can be listened to during a commute. A recent survey of secondary-school libraries found that borrowing rates for graphic novels rose noticeably even as overall book borrowing stayed flat. Online communities built around shared favorite titles have also given reading a social dimension it once lacked, letting fans discuss plot twists the same evening a new chapter appears. For some teenagers, then, a screen is not the enemy of reading but the very tool that introduced them to it.", "Teachers and parents, meanwhile, worry less about whether teenagers read and more about how carefully they read. Frequent short bursts of text on a screen can train the eye to skim rather than to absorb detail, according to several classroom observations. A student accustomed to scrolling quickly through captions may struggle when asked to follow a dense paragraph of argument, since sustained concentration is itself a skill that weakens without regular practice. Researchers say this habit forms early, often before a student ever encounters a genuinely difficult text. Once established, it can be hard to reverse, according to several long-term literacy studies.", "Schools have responded with strategies designed to rebuild that stamina without dismissing digital formats outright. Reading circles built around graphic novels, timed silent-reading periods, and assignments that pair a printed chapter with an online discussion forum are becoming common in secondary classrooms. Whether these efforts succeed may depend less on the format teenagers choose than on whether adults treat any sustained, voluntary reading, printed or digital, as worth encouraging in the first place."], questions: [{ q: "According to the passage, what did a recent library survey find?", options: ["Borrowing of audiobooks rose sharply while graphic novel demand fell.", "Overall book borrowing increased noticeably across every age group surveyed.", "Borrowing of graphic novels increased while overall borrowing remained steady.", "Borrowing of graphic novels declined slightly despite continued steady demand."], answer: 2 }, { q: "Which of the following best expresses the main idea of the passage?", options: ["Public libraries have adapted their collections to include graphic novels.", "Teenagers have largely abandoned reading in favor of digital entertainment.", "Reading habits among teenagers are shifting in form, not disappearing.", "All forms of concentrated reading are declining across every age group."], answer: 2 }, { q: "The word \"broadened\" in paragraph 1 is closest in meaning to _______.", options: ["multiplied", "expanded", "digitized", "broadcasted"], answer: 1 }, { q: "According to the passage, why do a short video or notification appeal more immediately than a novel does?", options: ["Digital habits have changed reading's shape rather than erasing it.", "A short video offers entertainment far faster than novels.", "Teenagers juggle schoolwork, jobs, and social commitments most evenings.", "Novels can be read faster than short online videos."], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a reason teenagers read fewer printed books?", options: ["A shortage of books available in school and public libraries.", "Constant entertainment available through videos and messaging apps.", "Competing demands from part-time jobs and social commitments.", "Difficulty maintaining focus after frequent skimming of short texts."], answer: 0 }, { q: "The word \"it\" in paragraph 4 refers to _______.", options: ["a genuinely difficult text", "a student's concentration", "the skimming habit", "classroom observations"], answer: 2 }, { q: "According to the passage, what happens to concentration without regular practice?", options: ["It strengthens greatly whenever screen use increases instead.", "It transfers easily and fully from short texts to paragraphs.", "It weakens, much like any skill that goes unused.", "It remains largely unaffected by how someone typically reads."], answer: 2 }, { q: "The word \"stamina\" in paragraph 5 is closest in meaning to _______.", options: ["endurance", "energy", "curriculum", "stability"], answer: 0 }, { q: "What can be inferred from the passage about the future of teenage reading?", options: ["Printed books will completely disappear as libraries shift entirely to digital formats.", "Better concentration among teenagers will lead them to abandon short-form video content.", "Teachers today mostly worry about how carefully young readers actually read.", "Reading will likely persist through new digital forms rather than vanish."], answer: 3 }, { q: "What is the author's overall attitude toward the change in teenage reading habits?", options: ["Strongly alarmed that today's teenagers have stopped reading for good.", "Cautiously optimistic, seeing both genuine loss and real adaptation.", "Fully confident that classroom strategies will solve the problem soon.", "Mildly disappointed that teenagers rarely choose printed books anymore."], answer: 1 }] },
    { title: "FOMO: The Fear of Missing Out in the Digital Age", paragraphs: ["Long before smartphones existed, people occasionally worried that a gathering elsewhere might prove more memorable than the one they had chosen to attend. What has changed is not the feeling itself but its constant availability, since a single glance at a phone can now confirm, in real time, exactly what one is missing. Researchers use the term FOMO - fear of missing out - to describe this specific blend of anxiety and social comparison, and surveys suggest the sensation has become measurably more frequent since social platforms began delivering a continuous stream of other people's highlights.", "Platforms do not merely report what friends are doing; they subtly reward the sharing of moments engineered to look enviable. A birthday dinner photographed from a flattering angle, cropped to exclude an argument that happened minutes earlier, travels further than an honest account of an ordinary evening - and it is this selective curation, more than any single feature of the apps themselves, that appears to drive much of the anxiety users report. Scrolling through a feed built from such moments, a viewer compares an unfiltered private life against everyone else's carefully edited highlight reel, a comparison that is, by its very construction, impossible to win.", "Psychologists studying comparison theory note that this dynamic is not simply a matter of vanity or insecurity. Human beings appear wired to gauge their own standing by observing others, a tendency that served useful social functions long before any screen existed. What digital platforms have done is multiply the number of comparisons available at any given moment, from dozens encountered in a village to potentially thousands scrolled through before breakfast. Some researchers add that each new notification triggers a small, reliable release of dopamine, the same neurochemical involved in other reward-seeking behaviors, which may help explain why checking a feed can feel compulsive rather than optional.", "Whether this compulsion translates into lasting harm remains genuinely debated among specialists. Some studies link frequent social comparison to lower reported life satisfaction, while others find the relationship depends heavily on how a person already felt before opening the app. A teenager already prone to anxiety, for instance, may experience a sharper decline in mood after browsing than a peer who scrolls with detachment. This variation suggests that FOMO may function less as a single, uniform disorder and more as an amplifier of whatever emotional tendencies a person brings to the screen.", "Even accounting for this variation, several consistent patterns have emerged. Sleep researchers report that the temptation to check one more notification before bed tends to delay sleep onset, an effect that accumulates over weeks into measurable fatigue. Productivity studies describe a similar pattern during work hours, where the anticipation of a message can fragment concentration even when no notification actually arrives. None of this proves that digital platforms alone cause anxiety or poor sleep, only that they appear to interact with existing vulnerabilities in ways researchers are still working to untangle.", "Various remedies have been proposed, from scheduled phone-free hours to apps that track and limit screen time. Early evidence suggests that such tools help some users regain a sense of control, particularly when paired with a conscious decision about which notifications genuinely warrant interruption. Other researchers caution that a person who deletes one app often simply migrates the same anxious checking behavior to another, meaning the underlying comparison instinct, not the specific platform, may be the harder problem to solve.", "Whatever their eventual effectiveness, these countermeasures reflect a broader shift: FOMO is increasingly treated not as an individual failing but as a predictable response to environments engineered to exploit a very old psychological wiring. Whether future platforms will be redesigned to lessen that exploitation, or will instead refine it further, is a question current evidence does not yet allow anyone to answer with confidence."], questions: [{ q: "According to the passage, what has actually changed about FOMO in the digital age?", options: ["People occasionally worried that a gathering elsewhere would be more memorable.", "Social platforms invented the anxious feeling of missing a social event.", "The feeling now comes with instant, constant confirmation of what's happening elsewhere.", "Surveys show the feeling has stayed at roughly the same frequency for decades."], answer: 2 }, { q: "The word \"engineered\" in paragraph 2 is closest in meaning to _______.", options: ["deliberately crafted", "slightly adjusted", "widely shared", "engendered"], answer: 0 }, { q: "Which of the following best expresses the main idea of the passage?", options: ["Dopamine release mainly explains why checking notifications feels compulsive to users.", "FOMO is an old feeling made stronger by curated digital comparison.", "Digital platforms are described as the sole cause of user anxiety.", "Every social media user experiences the same level of comparison-driven anxiety."], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a proposed countermeasure to FOMO?", options: ["Scheduling regular blocks of complete phone-free time.", "Using apps that track and limit total screen time.", "Consciously deciding which notifications genuinely deserve an interruption.", "Attending professional therapy sessions designed specifically for FOMO."], answer: 3 }, { q: "According to the passage, what does the release of dopamine appear to help explain?", options: ["Human beings gauge their own standing by observing others.", "Why checking a feed can feel difficult to resist.", "Why teenagers specifically feel more anxious than adults do.", "Why thousands of daily comparisons cause permanent psychological damage."], answer: 1 }, { q: "The phrase \"This variation\" in paragraph 4 refers to _______.", options: ["specialist debate itself", "a teenager's mood swing", "differing personal reactions", "life satisfaction studies"], answer: 2 }, { q: "The word \"exploit\" in paragraph 7 is closest in meaning to _______.", options: ["make use of", "keep track of", "explore", "take advantage of"], answer: 3 }, { q: "According to the passage, what do some researchers caution about phone-limiting apps?", options: ["Users may simply shift the same anxious habit to a different app.", "Early evidence suggests such tools help some users regain control.", "Every user who deletes an app stops checking their phone entirely.", "App developers deliberately design tools to increase anxious checking behavior."], answer: 0 }, { q: "What can be inferred about the future of FOMO research, based on the passage?", options: ["Future platforms will definitely be redesigned to eliminate FOMO completely.", "Reduced anxiety among users will lead platforms to abandon curated content.", "Researchers will likely keep investigating rather than reach a settled conclusion soon.", "Sleep researchers report that late-night notification checking delays sleep onset."], answer: 2 }, { q: "What is the author's overall attitude toward FOMO, as conveyed in the passage?", options: ["Enthusiastic that digital detox apps will fully resolve the problem soon.", "Balanced and inquiring, treating FOMO as a complex, still-unresolved phenomenon.", "Alarmed that social media is clearly destroying an entire generation's mental health.", "Mildly dismissive of concerns about social media's effect on wellbeing."], answer: 1 }] },
    { title: "Electromagnetic Pollution: The Hidden Impact of Mobile Signals", paragraphs: ["By one estimate, several billion people now carry a device on their person that continuously exchanges radio-frequency signals with a nearby base station, yet the health implications of this near-constant exposure remain, according to some researchers, less settled than either regulators or manufacturers tend to publicly acknowledge. Concern over so-called electromagnetic pollution has circulated for decades, resurfacing periodically whenever a new generation of wireless technology is introduced, though the scientific debate itself has shifted considerably from its earlier, more alarmist framing.", "Radio-frequency signals belong to the non-ionizing portion of the electromagnetic spectrum, meaning they lack the energy to strip electrons from atoms or directly damage DNA in the way that X-rays or gamma rays can. This distinction underlies most existing safety standards, which are calibrated primarily around a well-established thermal effect: sufficiently intense exposure heats human tissue, and regulatory limits are set with a substantial safety margin below the threshold at which measurable heating begins. What remains contested, however, is whether biological effects can occur below that thermal threshold at all.", "International bodies responsible for setting exposure guidelines maintain that, once thermal effects are excluded, current evidence does not establish a causal link between typical mobile-phone use and disease. Some independent researchers do not dispute the absence of a proven mechanism but argue that absence of proof is not equivalent to proof of safety, particularly given that widespread civilian exposure to this specific frequency range and duration is a relatively recent phenomenon in evolutionary terms. This gap between institutional confidence and lingering scientific caution is itself part of what fuels ongoing public unease .", "That unease is not entirely without empirical grounding, though the grounding is considerably weaker than headlines sometimes suggest. A handful of laboratory studies have reported subtle changes in cellular activity or sleep architecture following radio-frequency exposure at levels within legal limits, and these findings are occasionally cited as vindication by advocacy groups. Closer inspection of this literature, however, reveals a familiar pattern: the positive results tend to cluster in studies with smaller sample sizes, less rigorous blinding, or exposure conditions that are difficult to replicate, while larger, more tightly controlled trials have generally failed to reproduce the same effects.", "The resulting gap between a cautious scientific consensus and a more anxious public mood is not unique to this topic, but it is amplified here by the sheer scale of daily exposure and by the intuitive, if scientifically contested, sense that something invisible and pervasive ought to have some effect. Media coverage that juxtaposes a dramatic individual study against a duller regulatory reassurance can leave audiences with the impression of a fifty-fifty debate, even when the weight of accumulated evidence leans heavily toward one side.", "The rollout of denser wireless networks has reopened some of these questions in a new form. Newer network generations often rely on a greater number of lower-power transmitters placed closer to users, rather than fewer high-power towers spaced far apart, which proponents argue may actually reduce average individual exposure even as the total number of signal sources increases. Critics counter that this claim , while plausible in principle, has not yet been verified across the full range of real-world deployment patterns, and that regulatory frameworks have arguably not kept pace with the speed of network densification.", "Taken together, the available evidence does not currently justify alarm, but it likewise does not fully retire the underlying scientific question, which is less \"is this dangerous\" than \"how confidently can absence of proven harm be treated as proof of safety.\" Continued independent monitoring, rather than either dismissal or panic, appears to be the position most consistent with where the research genuinely stands today."], questions: [{ q: "According to the passage, what is the basis for most existing radio-frequency exposure standards?", options: ["Radio-frequency signals reportedly lack sufficient energy to damage DNA directly.", "A safety margin set below the point where measurable tissue heating starts.", "International advocacy groups determine the thermal threshold used in guidelines.", "Limits are set exactly at the threshold where tissue heating begins."], answer: 1 }, { q: "The word \"unease\" in paragraph 3 is closest in meaning to _______.", options: ["terror", "regulation", "apprehension", "disease"], answer: 2 }, { q: "Which of the following best expresses the main idea of the passage?", options: ["Scientific caution, not alarm, best matches current evidence on exposure.", "Regulatory bodies mainly rely on thermal effects for safety limits.", "Independent research has now proven mobile signals directly cause disease.", "All wireless technology should be avoided until proven completely harmless."], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a reason for continued scientific caution about mobile-signal exposure?", options: ["Widespread exposure to this specific frequency range is evolutionarily recent.", "Some small studies report subtle effects within legal exposure limits.", "Regulatory frameworks may not have kept pace with network densification.", "Independent laboratories have found consistent evidence of DNA damage from signals."], answer: 3 }, { q: "According to the passage, what pattern do larger, more rigorous studies tend to show regarding non-thermal effects?", options: ["Larger studies consistently confirm the same subtle cellular changes.", "They generally fail to reproduce the effects smaller studies reported.", "A handful of laboratory studies reported subtle changes in sleep architecture.", "All laboratory studies regardless of size report identical results."], answer: 1 }, { q: "The phrase \"this claim\" in paragraph 6 refers to _______.", options: ["the network density figure", "the regulatory framework itself", "the exposure-reduction argument", "the real-world deployment pattern"], answer: 2 }, { q: "The word \"vindication\" in paragraph 4 is closest in meaning to _______.", options: ["confirmation", "acknowledgment", "regulation", "vindictiveness"], answer: 0 }, { q: "According to the passage, why can media coverage leave audiences with a misleading impression of the scientific debate?", options: ["Regulators deliberately exaggerate the dangers to attract public attention.", "Every study on this topic receives equal, extensive media coverage.", "The scale of daily signal exposure is genuinely larger than before.", "It often pairs one dramatic study against a duller regulatory reassurance."], answer: 3 }, { q: "What can be inferred about the relationship between scientific confidence and public perception, based on the passage as a whole?", options: ["Because studies disagree, mobile phones are probably still somewhat dangerous.", "Public anxiety can persist even when accumulated evidence favors reassurance.", "Public confidence in safety has caused scientists to relax their standards.", "Newer networks rely on more numerous, lower-power transmitters placed closer to users."], answer: 1 }, { q: "What is the author's overall stance toward concerns about electromagnetic pollution from mobile signals?", options: ["Firmly dismissive of any laboratory evidence suggesting non-thermal effects exist.", "Fully convinced that denser networks pose no meaningful new questions.", "Measured skepticism toward alarm, paired with openness to real uncertainty.", "Quietly alarmed that regulators have consistently misled the public on safety."], answer: 2 }] },
    { title: "Vietnam in the Global Economic Landscape: Challenges and Opportunities", paragraphs: ["Vietnam's transformation from a predominantly agrarian economy into one of Southeast Asia's more prominent manufacturing and export hubs did not occur through any single policy decision, but the country's accession to a dense web of trade agreements over the past two decades arguably provided the institutional scaffolding on which subsequent investment could be built. That this integration coincided with a broader restructuring of global supply chains away from single-country concentration may partly explain why Vietnam, rather than several comparably positioned neighbors, became a preferred alternative destination for manufacturers seeking to diversify.", "Foreign direct inflows did not arrive evenly across sectors; electronics assembly, footwear, and textiles absorbed a disproportionate share, reflecting less a deliberate industrial strategy than the sequencing of which multinational firms moved first and the infrastructure that subsequently grew up around them. Labor costs meaningfully below those of coastal China provided an initial pull, though this advantage has narrowed as wages have risen alongside productivity gains, suggesting that whatever advantage remains increasingly rests on logistics, trade-agreement access, and accumulated manufacturing expertise rather than on cost alone.", "A structural feature of this growth model, however, complicates any straightforwardly celebratory account: a substantial proportion of the components assembled into Vietnamese exports are themselves imported, meaning that headline export figures may overstate the domestic value genuinely captured within the country. Some economists argue that this pattern does not necessarily indicate a failure of industrial policy so much as a predictable early stage in a longer upgrading trajectory, one that earlier East Asian economies also passed through; others are less convinced that the transition to higher-value domestic production is proceeding quickly enough to avoid a prolonged plateau .", "Closing that gap depends substantially on human capital, an area where progress, while real, does not obviously match the pace of industrial expansion. Vocational training systems have expanded, and technical universities have adjusted curricula toward manufacturing and, increasingly, semiconductor-adjacent skills, yet employers in higher-value segments continue to report difficulty filling specialized engineering roles. Whether this reflects a temporary lag that education reform will eventually close, or a more persistent mismatch, is a question current data does not yet settle with confidence.", "External conditions complicate the picture further, and not always in a single direction. Rising trade tensions between larger economies have, on one hand, accelerated the very diversification that benefited Vietnam in the first place; on the other, an economy this dependent on export demand from a small number of major trading partners is correspondingly exposed when those partners slow down, a vulnerability that became apparent during recent periods of weakened global demand. Some analysts suggest that Vietnam's exposure may deepen rather than ease as it absorbs a growing share of global manufacturing capacity.", "Policy responses have concentrated on infrastructure, digital transformation, and a stated ambition to participate more fully in renewable energy and semiconductor supply chains, sectors widely regarded as higher-value than the assembly work that currently dominates. Substantial public investment has been directed toward ports, transmission capacity, and industrial zones, though execution has, according to several assessments, lagged the pace originally announced, particularly for large infrastructure projects requiring extensive land clearance and multi-agency coordination. Whether announced ambitions translate into completed capacity on the anticipated timeline remains, by most independent accounts, genuinely uncertain.", "Taken as a whole, Vietnam's trajectory is neither a straightforward success story nor a cautionary tale, but something closer to a conditional one: continued growth appears likely so long as global trade patterns remain broadly favorable and domestic upgrading proceeds, yet neither of those conditions is guaranteed, and the country's medium-term position will depend considerably on which of the currently unresolved trends ultimately dominates."], questions: [{ q: "According to the passage, what do some economists argue about Vietnam's reliance on imported components?", options: ["It definitely proves Vietnam's industrial policy has completely failed.", "It has no relationship at all to how other East Asian economies developed.", "It shows every developing economy inevitably follows the same exact path.", "It may reflect an early, ordinary stage of a longer upgrading process."], answer: 3 }, { q: "The word \"plateau\" in paragraph 3 is closest in meaning to _______.", options: ["decline", "stagnation", "expansion", "platitude"], answer: 1 }, { q: "Which of the following best expresses the main idea of the passage?", options: ["Vietnam's economic rise is real but its future depends on unresolved, conditional factors.", "Labor costs below coastal China initially attracted large-scale foreign investment.", "Vietnam's manufacturing success has already fully closed all structural gaps.", "Every emerging Southeast Asian economy will follow Vietnam's exact growth pattern."], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a challenge facing Vietnam's continued economic growth?", options: ["A shortage of specialized engineers in higher-value manufacturing segments.", "Heavy dependence on export demand from a small number of trading partners.", "A declining number of trade agreements available for Vietnam to join.", "Delays in executing large infrastructure projects as originally planned."], answer: 2 }, { q: "According to the passage, what does the passage suggest now underlies Vietnam's remaining manufacturing advantage?", options: ["Wages in Vietnam have fallen well below their earlier levels.", "Multinational firms no longer consider manufacturing costs when investing.", "Labor costs meaningfully below those of coastal China provided an initial pull.", "Logistics, trade-agreement access, and accumulated manufacturing expertise, not cost alone."], answer: 3 }, { q: "The word \"this\" in paragraph 4 refers to _______.", options: ["the curriculum adjustment itself", "the reported skills shortage", "semiconductor-adjacent training programs", "vocational training expansion"], answer: 1 }, { q: "The word \"scaffolding\" in paragraph 1 is closest in meaning to _______.", options: ["supporting framework", "temporary shelter", "trade surplus", "scaling"], answer: 0 }, { q: "According to the passage, what does the passage say about Vietnam's infrastructure execution?", options: ["Infrastructure projects have consistently finished well ahead of schedule.", "Every single infrastructure project has failed to make any progress at all.", "It has lagged behind the originally announced pace, according to several assessments.", "Substantial public investment has been directed toward ports and transmission capacity."], answer: 2 }, { q: "Based on paragraph 5 and the passage as a whole, what can be inferred about the relationship between global trade tensions and Vietnam's economy?", options: ["Trade tensions will certainly cause Vietnam's economy to collapse within a decade.", "Vietnam's growing exports have directly caused the trade tensions between larger economies.", "Vocational training systems have expanded to include semiconductor-adjacent skills.", "The same tensions that helped Vietnam initially may also increase its future vulnerability."], answer: 3 }, { q: "What is the author's overall stance toward Vietnam's economic trajectory?", options: ["Firmly convinced that Vietnam's manufacturing success is now fully secure.", "Cautiously hopeful, contingent on how currently unresolved factors ultimately play out.", "Fully confident that all announced infrastructure plans will be completed on time.", "Quietly pessimistic that Vietnam's growth model is already failing."], answer: 1 }] },
  ] },
  { id: "rd-095", num: 95, title: "Đề 095", timeMin: 60, parts: [
    { title: "The Alice in Wonderland Escape Room Experience", paragraphs: ["In the heart of Manchester, a new form of entertainment has captured the attention of local families and tourists alike. The Wonderland Escape Room opened its doors last spring, offering visitors a chance to step inside the classic story of Alice in Wonderland. Unlike traditional escape rooms that focus on horror or mystery, this attraction recreates the whimsical and colourful world created by Lewis Carroll. Since opening, tickets have sold quickly, and many sessions are fully booked weeks in advance, even though a single ticket costs more than most other escape rooms in the city.", "The experience begins in a small room designed to look like Alice's childhood garden. A guide dressed as the White Rabbit greets each group and explains the rules before disappearing through a tiny door at the back of the room. Visitors must then find a way to shrink themselves, just as Alice did in the book, by solving a puzzle involving a small bottle marked 'Drink Me'. Once they solve it, they are led into a maze of connected rooms, each based on a different chapter of the story, such as the Mad Hatter's tea party and the Queen of Hearts' garden.", "Groups usually consist of four to six players, and each session lasts exactly sixty minutes from the moment the door closes. A host watches the group through hidden cameras placed around the rooms and can give hints if players get stuck for too long. According to the company's website, only about one in three groups manage to escape every room before the time runs out, which adds to the sense of challenge that keeps visitors coming back. Players do not need any special skills to take part, since the puzzles are designed so that both children over the age of eight and adults can enjoy them together.", "The escape room has received largely positive feedback since it opened last year. Local newspapers have described it as one of the most creative entertainment options in the city, while online reviews often praise the detailed costumes and realistic sets built by the design team. Some visitors, however, have mentioned that the Queen's garden room is noticeably more difficult than the earlier rooms, and a few groups have complained that the dim lighting there makes it hard to read certain clues on the walls. Despite this, the overall rating on booking websites remains high, at around 4.6 out of 5 stars.", "Beyond the puzzles themselves, the venue also runs a small café next door called the Mad Hatter's Table. There, guests can order brightly coloured drinks and cakes inspired by the story, such as a blue lemonade named 'Drink Me' and a chocolate tart called the 'Queen's Tart'. Many groups choose to celebrate a successful escape with a treat from the café, and staff sometimes take photographs of winning teams to post on the company's social media pages afterwards.", "Because of its popularity, the company that runs the Wonderland Escape Room has already announced plans to open two more branches, one in Birmingham and one in Leeds, later this year. The owners say they hope to bring the same sense of wonder to other parts of the country, and they are also considering adding a second Alice-themed room with new puzzles for visitors who want to return and try something different."], questions: [{ q: "What is the passage mainly about?", options: ["A new escape room in Manchester based on Alice in Wonderland and why it has become popular", "The puzzle involving a bottle marked 'Drink Me' at the start of the experience", "The difficulties visitors face in solving the Queen's garden room, despite the game's overall popularity", "Escape rooms have replaced cinemas as the most popular form of entertainment in Manchester"], answer: 0 }, { q: "How long does each session last?", options: ["45 minutes", "60 minutes", "75 minutes", "90 minutes"], answer: 1 }, { q: "Who greets each group at the start of the experience?", options: ["A guide dressed as the White Rabbit", "A guide dressed as the Mad Hatter", "A guide dressed as the Queen of Hearts", "A guide dressed as the Cheshire Cat"], answer: 0 }, { q: "According to the passage, about how many groups manage to escape every room before time runs out?", options: ["One in two", "One in three", "One in four", "One in five"], answer: 1 }, { q: "What must visitors do near the beginning of the experience?", options: ["Solve a puzzle to make themselves shrink", "Order a drink from the Mad Hatter's Table", "Take a photograph with the White Rabbit", "Choose which chapter of the story to start with"], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a feature of the Wonderland Escape Room experience?", options: ["Detailed costumes and realistic sets", "Live music performed by actors throughout the experience", "Hidden cameras that allow the host to watch players", "A café next door serving themed drinks and cakes"], answer: 1 }, { q: "The word \"whimsical\" in paragraph 1 is closest in meaning to _______.", options: ["playful", "frightening", "realistic", "expensive"], answer: 0 }, { q: "The word \"creative\" in paragraph 4 is closest in meaning to _______.", options: ["traditional", "inventive", "boring", "costly"], answer: 1 }, { q: "The word \"they\" in paragraph 2 refers to _______.", options: ["The visitors", "Alice and the White Rabbit", "The puzzle pieces", "The tiny door"], answer: 0 }, { q: "Based on the passage, it can be inferred that _______.", options: ["The escape room is intended mainly for young children under the age of eight", "The escape room is designed to appeal to a wide range of age groups, not just one type of visitor", "Visitors keep returning because the puzzles have become easier over time", "The company offers a café next door where guests can buy themed drinks"], answer: 1 }] },
    { title: "The Growing Popularity of Electric Suitcases in Japan", paragraphs: ["In recent years, a distinctive new product has begun to reshape how Japanese travellers move through crowded airports and train stations: the electric suitcase. Unlike conventional luggage, these motorised cases can carry themselves alongside their owner, and some models can even be ridden like a small vehicle across long terminal corridors. Although the technology originated abroad, Japanese manufacturers have refined it considerably, and sales figures suggest that demand within the domestic market has grown substantially over the past three years.", "Most electric suitcases rely on a combination of small motors built into the wheels, sensors that detect the owner's location, and a companion smartphone application. Once paired via Bluetooth, the case can follow its owner at a set distance, automatically adjusting its speed to avoid collisions with pedestrians. Some premium models are equipped with a small seat and handlebars, allowing a traveller to sit and be transported short distances, a feature that has proven particularly popular among elderly passengers who might otherwise struggle with long walks between gates.", "Several factors appear to be driving this trend. Japan's rapidly ageing population means that a growing proportion of domestic travellers may find it physically demanding to carry heavy bags unaided, and electric suitcases offer an obvious solution. At the same time, the resurgence of both domestic and international tourism following the reopening of borders has increased the overall volume of luggage passing through transport hubs, which tends to heighten demand for products that reduce physical strain. Social media exposure, particularly on platforms popular with younger travellers, has arguably reinforced the suitcase's appeal as much as its practical function has.", "The rise of these devices , however, has not been without complications. Several major airlines have voiced concerns about the lithium batteries that power the suitcases' motors, since damaged or overheating batteries pose a recognised fire risk in aircraft cargo holds. As a result, a number of carriers now require that any electric suitcase brought to check-in have a battery capacity below a specified threshold, and passengers who fail to comply may be asked to remove or leave the battery behind entirely. Several travellers have reported being turned away at the counter after purchasing suitcases without checking these regulations in advance.", "In response, manufacturers have increasingly designed suitcases with removable battery packs, allowing the battery to be taken out and carried separately in a passenger's hand luggage, where lithium battery rules are typically more flexible. Industry representatives have also begun working alongside regulators to establish clearer, standardised guidelines, in the hope of avoiding the kind of confusion that has affected early adopters of the technology. Whether these efforts will fully resolve the tension between innovation and airline safety requirements remains to be seen.", "Consumer reception, meanwhile, has been mixed but broadly favourable. [1] Price remains a significant barrier, as electric models can cost several times more than an equivalent conventional suitcase, [2] which may explain why uptake has so far been concentrated among frequent business travellers and affluent urban commuters rather than the general public. [3] Nevertheless, market analysts note that as production scales up and battery technology becomes cheaper, prices are likely to fall, [4] potentially widening the suitcase's appeal to a broader range of consumers within the next several years.", "Looking ahead, some commentators suggest that electric suitcases could represent a lasting shift in the luggage industry rather than a passing novelty, given the convergence of demographic pressure, tourism growth, and continuing technological refinement. Others remain more cautious, pointing out that unresolved regulatory questions and persistently high costs could limit the product's growth to a relatively narrow market segment. Whether the electric suitcase becomes a mainstream travel accessory or remains a niche convenience for a wealthier few will likely depend on how quickly these obstacles are addressed."], questions: [{ q: "What is the passage mainly about?", options: ["The various technologies used inside electric suitcase motors and sensors", "The growing popularity of electric suitcases in Japan, the reasons behind it, and the challenges they still face", "The safety problems caused by suitcase batteries and the airline bans that have resulted", "Electric suitcases have already replaced conventional luggage as the standard choice for most Japanese travellers"], answer: 1 }, { q: "According to the passage, why have some airlines placed restrictions on electric suitcases at check-in?", options: ["Because damaged or overheating lithium batteries pose a recognised fire risk", "Because the suitcases are too large to fit in overhead luggage compartments", "Because the motors interfere with aircraft navigation systems", "Because passengers often forget to switch the suitcases off"], answer: 0 }, { q: "What solution have manufacturers introduced to address airline battery restrictions?", options: ["Reducing the overall size of the suitcase shell", "Designing suitcases with removable battery packs that can be carried separately", "Installing solar panels to recharge the batteries mid-flight", "Offering free battery replacement services at airports"], answer: 1 }, { q: "According to the passage, which group has mainly purchased electric suitcases so far?", options: ["Frequent business travellers and affluent urban commuters", "Electric models can cost several times more than an equivalent conventional suitcase", "Budget-conscious students travelling abroad for the first time", "Elderly passengers travelling exclusively within Japan"], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a concern related to electric suitcases?", options: ["The high price compared to conventional suitcases", "Complaints about excessive noise from the suitcase motors", "The risk of fire caused by damaged batteries", "Confusion among early adopters over battery regulations"], answer: 1 }, { q: "The word \"resurgence\" in paragraph 3 is closest in meaning to _______.", options: ["revival", "decline", "expansion", "reduction"], answer: 0 }, { q: "The word \"affluent\" in paragraph 6 is closest in meaning to _______.", options: ["influential", "wealthy", "frugal", "elderly"], answer: 1 }, { q: "The phrase \"these devices\" in paragraph 4 refers to _______.", options: ["Electric suitcases", "Lithium batteries", "Smartphone applications", "Airline regulations"], answer: 0 }, { q: "Based on the passage, it can be inferred that _______.", options: ["Manufacturers have created suitcases with a small seat and handlebars for elderly travellers", "The future growth of electric suitcases in Japan will likely depend on how well manufacturers and regulators address safety and cost concerns", "Airlines introduced battery regulations because sales of electric suitcases had declined sharply", "Electric suitcases will inevitably replace all conventional luggage in Japan within the next few years"], answer: 1 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'This price gap, however, is expected to narrow considerably within the next few years.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 2 }] },
    { title: "The Positive Effects of Video Games", paragraphs: ["For decades, public discourse surrounding video games has been dominated by concerns over aggression, addiction, and social isolation. Yet a growing body of academic research suggests that this narrative, while not entirely without merit, has obscured a range of cognitive and social benefits that gaming can confer under the right conditions. Researchers studying action games in particular have found measurable improvements in visual attention, task-switching speed, and the capacity to track multiple moving objects simultaneously — skills that transfer to real-world activities such as driving and even certain surgical procedures.", "One of the more striking findings to emerge from this research concerns what psychologists term 'probabilistic reasoning'. Many modern games require players to make rapid decisions under conditions of incomplete information, weighing risk against potential reward within fractions of a second. Longitudinal studies tracking adolescent players over several years have reported that those who regularly engaged with strategically demanding games showed improvements in decision-making tasks unrelated to gaming itself, though researchers caution that establishing a direct causal pathway remains methodologically difficult given the number of confounding variables involved.", "Beyond cognition, multiplayer games have increasingly been examined through a social lens. Contrary to the popular image of the isolated gamer, survey data indicates that a substantial proportion of players use gaming primarily as a means of maintaining friendships, particularly among those who have relocated away from childhood social networks. Collaborative titles that require coordinated strategy, communication, and division of labour appear to foster a distinct form of teamwork that some researchers argue is comparable to the collaborative skills developed through organised team sports, albeit expressed through a digital rather than physical medium.", "Educational applications of gaming have also expanded considerably. So-called 'serious games' — those designed explicitly with a learning objective in mind — have been deployed in fields ranging from medical training to language acquisition. A number of hospitals now incorporate game-based simulations into surgical resident training, citing evidence that trainees who practised on such simulations before entering the operating theatre made fewer procedural errors than those who did not. Whether this advantage persists once the novelty of the technology has worn off, however, is a question that longer-term studies have yet to fully resolve.", "Emotional regulation represents a further, less intuitive area of benefit identified by researchers. Certain genres, particularly those emphasising exploration or puzzle-solving over competition, have been associated with reduced self-reported stress levels immediately following play, an effect some clinicians have begun to harness in therapeutic contexts for patients experiencing anxiety. This is not to suggest that all games produce this effect uniformly; highly competitive titles with a strong emphasis on player-versus-player conflict have shown more mixed, and occasionally contradictory, results across different studies, suggesting that genre and context matter considerably more than the medium itself.", "Critics of this body of research are quick to point out its limitations. Much of the existing literature relies on self-reported data, correlational designs, or sample populations drawn disproportionately from existing gaming communities, all of which complicate efforts to generalise findings to the wider population. Furthermore, several prominent studies once cited as evidence of cognitive benefit have failed to replicate under more rigorous experimental conditions, prompting some researchers to call for greater caution before drawing firm conclusions. Proponents counter that the failure of individual studies to replicate does not invalidate the broader pattern of evidence, and that inconsistent findings are, in any complex and rapidly evolving field of study, to be expected rather than treated as disqualifying.", "What emerges from this ongoing debate is not a simple verdict of 'good' or 'bad', but rather a more nuanced picture in which the effects of gaming appear highly dependent on genre, frequency, social context, and the individual player's existing psychological profile. Researchers increasingly argue that future work should move away from broad, medium-level questions — is gaming good or bad — toward more specific inquiries into which particular game mechanics, played under which particular conditions, produce which particular outcomes."], questions: [{ q: "What is the main idea of the passage?", options: ["Video games cause measurable harm to adolescents' decision-making abilities", "The effects of video games are complex and depend heavily on genre, frequency, and social context rather than being simply good or bad", "Multiplayer games are primarily valuable because they replace the need for organised team sports", "Serious games have completely replaced traditional teaching methods in medical education"], answer: 1 }, { q: "According to the passage, what do many modern games require players to do?", options: ["Complete tasks slowly to maximise long-term accuracy", "Avoid interacting with other players entirely", "Memorise fixed sequences of moves in advance", "Make rapid decisions under conditions of incomplete information"], answer: 3 }, { q: "What evidence does the passage give regarding surgical resident training?", options: ["Trainees who practised on game-based simulations made fewer procedural errors than those who did not", "Hospitals have stopped using simulations because they proved ineffective over time", "All surgical residents are now required to play action games before surgery", "Simulation-based training has replaced all traditional forms of surgical education"], answer: 0 }, { q: "According to the passage, why do a substantial proportion of players use gaming?", options: ["To avoid all forms of face-to-face social contact permanently", "To maintain friendships, particularly after relocating away from childhood social networks", "To compete professionally in organised tournaments", "To reduce their reliance on smartphone applications"], answer: 1 }, { q: "According to the passage, which types of games have been associated with reduced self-reported stress?", options: ["Those emphasising exploration or puzzle-solving over competition", "Highly competitive titles emphasising player-versus-player conflict", "Games requiring the fastest possible reaction times", "Games designed exclusively for professional esports training"], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a limitation of existing gaming research?", options: ["Reliance on self-reported data and correlational designs", "Sample populations drawn disproportionately from existing gaming communities", "All studies on gaming benefits have been fully replicated without exception", "Failure of several prominent studies to replicate under rigorous conditions"], answer: 2 }, { q: "The word \"confer\" in paragraph 1 is closest in meaning to _______.", options: ["grant", "discuss", "remove", "predict"], answer: 0 }, { q: "The word \"replicate\" in paragraph 6 is closest in meaning to _______.", options: ["reproduce", "publish", "disprove", "summarise"], answer: 0 }, { q: "The word \"this\" in paragraph 5 refers to _______.", options: ["Highly competitive player-versus-player titles", "The therapeutic contexts used for anxiety patients", "The reduction in self-reported stress following play", "The genre of exploration-based games"], answer: 2 }, { q: "Based on the passage, it can be inferred that _______.", options: ["Researchers increasingly believe future studies should ask more specific questions about which mechanics and conditions produce which outcomes, rather than broad good-or-bad judgments", "The scientific community has reached full consensus that video games are universally beneficial", "Serious games have proven completely ineffective in every educational context studied", "Multiplayer games are now considered scientifically inferior to single-player games in every respect"], answer: 0 }] },
    { title: "The Mystery of the Easter Island Statues", paragraphs: ["Few archaeological sites have generated as much popular fascination, and as much scholarly disagreement, as Rapa Nui, the remote Pacific island more commonly known as Easter Island. Scattered across its landscape stand nearly nine hundred monumental stone figures, known as moai, some exceeding ten metres in height and weighing dozens of tonnes. The enduring puzzle is not merely how a comparatively small Polynesian population managed to carve such figures using stone-age tools, but how they subsequently transported them, in some cases several kilometres, from the quarry to their final ceremonial platforms.", "For much of the twentieth century, the dominant explanation held that moai were dragged horizontally on wooden sledges, a process that would have required the felling of substantial quantities of timber to serve as rollers and levers. This account dovetailed with a broader narrative — popularised in the 1990s — that framed Rapa Nui's history as a cautionary tale of ecological self-destruction: [1] islanders, driven by ritual competition to construct ever more statues, felled the island's forests until the resulting deforestation triggered soil erosion, agricultural collapse, and ultimately a catastrophic decline in population. [2] This narrative, often referred to as the 'ecocide' hypothesis, achieved considerable popular traction, in part because it functioned so effectively as an allegory for contemporary anxieties about global environmental degradation. [3]", "More recent archaeological and experimental work, however, has complicated this once-tidy account considerably. Researchers conducting field experiments in the early 2010s demonstrated that a moai could, with a team of as few as eighteen people manipulating ropes attached at different points around the statue's base, be made to rock from side to side and effectively 'walk' upright along a prepared roadway — a method requiring neither sledges nor extensive timber consumption. Analysis of the shape of surviving roadways, along with the distinctive D-shaped base found on many transported statues, lends further support to this alternative, suggesting the statues were engineered from the outset to be moved upright rather than dragged flat. [4]", "The ecocide narrative has faced further scrutiny on demographic grounds. Skeletal and archaeological evidence increasingly suggests that the island's population did not, in fact, collapse dramatically prior to European contact in 1722, as the ecocide hypothesis maintains; rather, population decline appears to correlate more closely with the introduction of European diseases, forced removal of islanders for slave labour in the mid-nineteenth century, and the resulting disruption of the island's social and agricultural systems. This does not necessarily mean that deforestation played no role whatsoever in the island's ecological history — palynological evidence clearly documents a substantial reduction in forest cover over several centuries — but it does suggest that attributing this change solely to unsustainable statue-building ritual, independent of other contributing factors such as the introduction of the Polynesian rat, which is known to have preyed heavily on palm seeds, may overstate a single cause at the expense of a more genuinely multi-causal explanation.", "What further complicates any tidy narrative is the question of motive and social organisation. Rather than a single, undifferentiated society competing purely for status through statue construction, evidence increasingly points to a lineage-based social structure in which competing clans each maintained their own ceremonial platforms, or ahu, with statue construction functioning simultaneously as religious observance, territorial marker, and expression of lineage prestige. Whether this competitive dynamic accelerated resource depletion beyond sustainable levels, or whether the island's ecology would have declined along a broadly similar trajectory regardless of statue-building, remains a question that current evidence does not permit us to answer with confidence.", "Taken together, this body of research does not so much overturn the notion that Rapa Nui's history involved significant ecological change as it does undermine the simplicity of the story once told about it. The reduction of a genuinely multi-causal historical process — encompassing climate, disease, colonial disruption, and ecological pressure — to a single morality tale about reckless deforestation may have served a rhetorically convenient purpose for contemporary environmental discourse, but it does not withstand close examination of the archaeological and demographic record. The author's broader argument is not that Rapa Nui's ecological history is unimportant, but rather that its explanatory value is undermined when it is invoked as a simplified allegory rather than examined on its own considerably more complicated terms."], questions: [{ q: "What is the author's main purpose in the passage?", options: ["To argue that Rapa Nui's ecological history is unimportant compared to its social structure", "To challenge the simplified 'ecocide' narrative and show that Rapa Nui's history involves a more complex, multi-causal process", "To prove that the moai statues were never moved from their original quarry", "To defend the ecocide hypothesis against all recent archaeological criticism"], answer: 1 }, { q: "According to the passage, how many people were needed to make a moai 'walk' upright in the field experiments?", options: ["As few as eighteen", "Roughly fifty", "Over one hundred", "Exactly twelve"], answer: 0 }, { q: "According to the passage, what physical feature of surviving statues supports the 'walking' theory?", options: ["The unusually light weight of statues found near the coast", "The distinctive D-shaped base found on many transported statues", "Rope marks found exclusively on statues near the quarry", "The rounded, circular base found on all Rapa Nui statues"], answer: 1 }, { q: "According to the passage, what does evidence suggest actually correlates most closely with the island's population decline?", options: ["European diseases and forced removal of islanders for slave labour", "A sudden agricultural collapse caused entirely by statue-building rituals", "A catastrophic decline that occurred well before European contact in 1722", "The complete disappearance of the island's forest cover"], answer: 0 }, { q: "According to the passage, what role did the Polynesian rat play in the island's ecological history?", options: ["It was introduced by European colonists in the nineteenth century", "It caused the extinction of the island's native bird populations", "It is known to have preyed heavily on palm seeds", "It was used by islanders to help transport the statues"], answer: 2 }, { q: "According to the passage, which of the following is NOT presented as a factor contributing to the island's population decline?", options: ["European diseases introduced after contact in 1722", "Forced removal of islanders for slave labour", "Disruption of social and agricultural systems", "A sudden volcanic eruption that destroyed the island's water supply"], answer: 3 }, { q: "The word \"dovetailed\" in paragraph 2 is closest in meaning to _______.", options: ["aligned", "conflicted", "originated", "weakened"], answer: 0 }, { q: "The word \"palynological\" in paragraph 4 most likely relates to the study of _______.", options: ["ancient pollen and plant remains", "population census records", "volcanic rock formations", "ocean current patterns"], answer: 0 }, { q: "The word \"this\" in paragraph 5 refers to _______.", options: ["The competitive dynamic between rival lineage-based clans", "The construction of ceremonial platforms called ahu", "The introduction of European diseases after 1722", "The field experiments conducted in the early 2010s"], answer: 0 }, { q: "Based on the passage, which statement best reflects the author's overall stance toward the ecocide hypothesis?", options: ["It is entirely fabricated and unsupported by any archaeological evidence whatsoever", "It captures an important truth but its explanatory power is undermined when treated as a simplified single-cause allegory rather than examined within a genuinely multi-causal context", "It remains the most accurate and complete explanation available despite recent criticism", "It should be replaced entirely by an explanation centred solely on the Polynesian rat"], answer: 1 }] },
  ] },
];
